    x_cable: np.ndarray
    y_cable: np.ndarray
    boat: tuple[float, float]
    rov: tuple[float, float]
    l_target: float
    n_segments: int
    n_target: int
    # Alignés sur CableSolver._normalize_cable_length (optionnels, pour persistance / debug)
    k_tail: int | None = None
    k_max: float | None = None
    bidirectional: bool | None = None
    _from_direction: str | None = None
    t: float | None = None

    @property
    def P(self) -> np.ndarray:
        return np.stack([self.x_cable, self.y_cable], axis=1)


